update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance corrective","mecanisme":"L''intervention exécutée après la défaillance. Cette page donne la définition, la différence avec la curative et la palliative, et le coût réel d''une panne. Puis elle montre comment ramener le correctif à une part minoritaire de votre budget.","cta":"Demander une intervention","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option."},{"type":"chiffres","chiffres":[{"valeur":"La corrective immédiate.","libelle":"On intervient tout de suite parce que l''immobilisation pèse plus lourd que tout le reste","detail":"C''est la maintenance d''urgence, aussi appelée réactive."},{"valeur":"La corrective différée.","libelle":"La panne est constatée, l''intervention est planifiée sur la prochaine fenêtre disponible, la pièce est commandée sans transport express","detail":"Moins de stress, moins de dépense inutile."},{"valeur":"La condition pour différer.","libelle":"Un équipement redondant, ou un mode dégradé acceptable","detail":"Sans cette condition, la décision est déjà prise à votre place."},{"valeur":"Aucune dépense tant que rien ne casse.","libelle":"Pas de plan, pas de ronde, pas d''immobilisation programmée","detail":"Sur du matériel de faible enjeu, c''est le choix rationnel."},{"valeur":"Une mise en œuvre simple.","libelle":"Aucune organisation lourde, aucun logiciel obligatoire pour démarrer."},{"valeur":"Le bon usage type","libelle":"un convoyeur doublé, où l''indisponibilité d''une voie ne stoppe pas la fabrication."},{"valeur":"La facture réelle explose.","libelle":"Heures de nuit, pièce en urgence, transport express, production perdue","detail":"Une intervention non planifiée coûte plusieurs fois une opération préventive équivalente."},{"valeur":"Le matériel vieillit plus vite.","libelle":"Un équipement qui casse avant d''être entretenu raccourcit son cycle de vie à chaque épisode."},{"valeur":"Les équipes s''épuisent.","libelle":"Le préventif saute, le retard s''accumule, et la spirale des heures supplémentaires commence."},{"valeur":"La sécurité se dégrade.","libelle":"Un travail effectué sous pression multiplie les risques, pour vos opérateurs comme pour l''installation."},{"valeur":"+ 120","libelle":"clients industriels, dont plus de 80 réguliers","detail":"La plupart sont arrivés par une panne"},{"valeur":"10 %","libelle":"des candidats retenus, chaque technicien est évalué en entretien technique et comportemental"},{"valeur":"24/24 et 7/7","libelle":"astreinte en option, partout en France"}]},{"type":"probleme","punchline":"Beaucoup de sites paient trois fois la même panne. Le composant, la production perdue, puis la récidive.","puces":[{"accroche":"Le tarif se négocie machine à l''arrêt.","texte":"Personne ne fait un bon achat un vendredi à 16h avec une ligne bloquée et un client qui attend."},{"accroche":"Le technicien repart de zéro à chaque fois.","texte":"Aucun historique, aucune connaissance du parc, et le temps de diagnostic se paie une deuxième fois."},{"accroche":"On traite le symptôme, jamais la cause.","texte":"Le composant neuf durera exactement aussi longtemps que son prédécesseur, et la même machine repassera par l''atelier dans deux mois."},{"accroche":"Le renfort arrive et ne sait pas faire.","texte":"Le pire scénario n''est pas la panne, c''est l''intervenant qui découvre le métier sur votre installation."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"Le diagnostic, la dépose, la réparation, les essais, la remise en service","texte":"sur tout le parc de production, d''utilités et de manutention."},"benefice":"La ligne repart, et vous savez pourquoi elle s''était arrêtée."},{"prestation":{"accroche":"La recherche de la cause racine","texte":", systématiquement, pas seulement le remplacement du composant fautif."},"benefice":"La troisième facture n''existe pas. Le problème sort de votre quotidien."},{"prestation":{"accroche":"L''intervention en urgence, la nuit et le week-end","texte":", avec astreinte 24/24 et 7/7 en option."},"benefice":"Une ligne bloquée un samedi ne devient pas un lundi perdu."},{"prestation":{"accroche":"Un écrit exploitable à chaque passage","texte":"cause, travaux, pièces remplacées avec références, recommandations."},"benefice":"Le dossier machine s''enrichit au lieu de se vider, et vous capitalisez."},{"prestation":{"accroche":"Le basculement des équipements coûteux vers le préventif ou le conditionnel","texte":", sur la base de votre historique chiffré."},"benefice":"La part de l''imprévu dans votre budget baisse, et vous pouvez le prouver."},{"prestation":{"accroche":"Aucune marge sur les pièces","texte":"nous consultons le marché fournisseur au prix réel."},"benefice":"La recommandation de remplacement est indépendante de ce qu''elle nous rapporterait."}],"prose":[{"texte":"Ligne bloquée maintenant ? Voir le [dépannage industriel](/offres/depannage-industriel/). Pour sortir du tout correctif, voir le [contrat de maintenance Zéro arrêt](/offres/zero-arret/). Migen est une [entreprise de maintenance industrielle](/offres/) présente partout en France."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la situation.","texte":"Équipement, symptôme, contexte. Deux minutes de description précise font gagner une heure de diagnostic sur site."},{"titre":"Nous qualifions et nous engageons la prise en charge.","texte":"Bon interlocuteur, bon profil, bonne date, décidés au téléphone et pas trois jours plus tard."},{"titre":"Les autorisations sont vérifiées avant le déplacement.","texte":"Consignation électrique, travail en hauteur, espaces confinés, zones classées, plan de prévention signé."},{"titre":"Le technicien intervient en autonomie.","texte":"Consignation, recherche de panne, réparation ou remplacement, essais en charge, application de vos consignes de sécurité."},{"titre":"Vous recevez un écrit exploitable.","texte":"Cause racine, travaux réalisés, pièces remplacées, recommandations, au format que votre GMAO sait lire."},{"titre":"Nous cherchons à supprimer la récidive.","texte":"Si une défaillance identique revient, nous proposons une action de fond plutôt qu''une énième réparation."}]},{"type":"garanties","puces":[{"accroche":"Un technicien qui sait faire, pas un technicien qui est libre.","texte":"Nous mobilisons le profil dont la compétence correspond au matériel. Chaque intervenant a passé une évaluation technique et comportementale en entretien, seuls 10 % des candidats sont retenus."},{"accroche":"Les règles de votre site priment sur les nôtres.","texte":"Plan de prévention appliqué, accueil au poste suivi à la lettre, procédures qualité et clauses de confidentialité respectées, comptes rendus intégrés à votre système documentaire."},{"accroche":"La sortie du correctif est chiffrée, pas promise.","texte":"Nous comparons vos dépannages de l''année écoulée avec le programme correspondant, chiffres en main. Si le contrat ne se justifie pas, nous le disons."}]},{"type":"cta","question":"Besoin d''un technicien sur une ligne qui vient de s''arrêter ?","bouton":"Demander une intervention","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure, astreinte 24/24 et 7/7."},{"type":"preuves","preuves":[{"titre":"Diagnostic sur site et réparation d''un parc machines défaillant, industrie lyonnaise","texte":"remise en état sans rachat de matériel neuf","lienLibelle":"Étude de cas JOINT LYONNAIS : défaillances machines","lienHref":"/preuves/joint-lyonnais/"},{"titre":"Maintenance curative des convoyeurs, trieurs et packaging, logistique","texte":"deux techniciens en poste sur site","lienLibelle":"Étude de cas GLS : maintenance curative","lienHref":"/preuves/gls-maintenance-curative/"},{"titre":"Remise en état d''un site de traitement des eaux industrielles, environnement","texte":"un électromécanicien habilité risque chimique mobilisé six mois","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"Montage, déplacement de machines et renfort technique ponctuel, matériaux","texte":"chantiers confiés au coup par coup","lienLibelle":"Étude de cas SOPREMA : travaux ponctuels","lienHref":"/preuves/soprema/"},{"titre":"Parc machines tenu en forte cadence, emballage","texte":"un technicien polyvalent intégré sur site","lienLibelle":"Étude de cas VPK : renfort maintenance","lienHref":"/preuves/vpk/"},{"titre":"Maintenance préventive et curative d''une fonderie et d''un usinage, automobile","texte":"tenue 7 jours sur 7, depuis octobre 2023","lienLibelle":"Étude de cas STELLANTIS : fonderie de Sept-Fons","lienHref":"/preuves/stellantis-fonderie-sept-fons/"}]},{"type":"objections","questions":[{"question":"La maintenance corrective coûte-t-elle plus cher que la préventive ?","reponse":"Sur un équipement critique, oui, et l''écart est large une fois la perte d''exploitation intégrée. Sur du matériel de faible enjeu, elle reste le choix économique. Le tri équipement par équipement est la seule méthode honnête, et c''est l''objet du diagnostic."},{"question":"Intervenez-vous en urgence, la nuit et le week-end ?","reponse":"Oui, partout en France, avec une astreinte 24/24 et 7/7 en option. Appelez le 04 78 33 72 05 : nous qualifions le dysfonctionnement avec vous et nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30."},{"question":"Faut-il un contrat pour faire appel à vous ?","reponse":"Non. Une panne isolée se traite en intervention ponctuelle. La question du contrat se pose sérieusement au-delà de trois interventions par an sur le même équipement, quand le budget n''est plus pilotable."},{"question":"Intervenez-vous si notre site est à Bordeaux, Lille ou Marseille ?","reponse":"Oui. Nos quatre agences sont à Lyon (siège), Montréal, Dubaï et Madrid, et nos équipes se déplacent partout en France. Le Sud-Ouest est couvert depuis Toulouse, les Hauts-de-France depuis Paris, le Sud-Est depuis Lyon, le Grand Ouest depuis Nantes."},{"question":"Qui répond de la sécurité pendant l''intervention ?","reponse":"Les autorisations exigées par votre installation sont vérifiées avant le déplacement. Le plan de prévention est signé et appliqué, comme l''impose la réglementation pour toute entreprise extérieure. Vos procédures qualité et vos clauses de confidentialité sont respectées sans exception."},{"question":"Pouvez-vous intégrer un technicien dans notre équipe sur site ?","reponse":"Oui, en prestation de services : un professionnel Migen travaille dans vos murs pour une durée définie avec vous, évalué au même niveau que pour nos interventions ponctuelles. Décrivez le besoin, nous vous disons si nous avons le profil et lequel."}]},{"type":"ctaFinal","question":"Besoin que cette panne soit la dernière de la série ?","bouton":"Demander une intervention","rappel":"04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure, astreinte 24/24 et 7/7."}]}'::jsonb where path = '/expertises/types-de-maintenance/maintenance-corrective/';
